// VOIDFORGE property tests (fuzzing): random inputs, generated by fast-check, are run through the page's own functions and the
// result is compared with an independent library (@scure, @noble) or a fixed rule. A failure prints the smallest input that
// breaks it and the seed that reproduces the whole run.
//
// Run: node tests/fuzz.test.mjs            (FUZZ_RUNS=n for more or fewer cases per property, FUZZ_SEED=n to repeat a run)
import fc from 'fast-check';
import fs from 'node:fs';
import nc from 'node:crypto';
import { entropyToMnemonic, mnemonicToSeedSync, validateMnemonic } from '@scure/bip39';
import { wordlist } from '@scure/bip39/wordlists/english';
import { HDKey } from '@scure/bip32';
import { bech32, bech32m, createBase58check } from '@scure/base';
import { secp256k1, schnorr } from '@noble/curves/secp256k1';
import { ripemd160 } from '@noble/hashes/ripemd160';
import { sha256 as nsha } from '@noble/hashes/sha256';
import { loadPage, ready, readHtml, makeReporter } from './harness.mjs';

const RUNS = Math.max(1, Math.round(Number(process.env.FUZZ_RUNS) || 60));   // whole numbers only: fast-check never ends with a fractional numRuns
const SEED = Number(process.env.FUZZ_SEED) || Date.now() % 2147483647;
const R = makeReporter();
console.log('fuzz: ' + RUNS + ' runs per property, seed ' + SEED + ' (FUZZ_SEED=' + SEED + ' repeats this run)');
const PAGE = process.env.FUZZ_PAGE ? fs.readFileSync(process.env.FUZZ_PAGE, 'utf8') : readHtml();   // FUZZ_PAGE: test another copy (used to check that the tests can fail)
const w = await ready(loadPage(PAGE));
const hex = (b) => Buffer.from(b).toString('hex');
const b58 = createBase58check(nsha), h160 = (b) => ripemd160(nsha(b));

// One property: run it, report PASS or the shrunk counterexample.
async function prop(name, arb, check, runs = RUNS) {
  try {
    await fc.assert(fc.asyncProperty(arb, async (v) => { const r = await check(v); if (r !== true) throw new Error(typeof r === 'string' ? r : 'property is false'); }), { numRuns: runs, seed: SEED, endOnFailure: true });
    R.ok(true, name + ' (' + runs + ' random cases)');
  } catch (e) { R.ok(false, name + ': ' + String(e.message).split('\n').slice(0, 6).join(' | ')); }
}

// Reference addresses from @scure/@noble, for one public key and address type.
function refAddr(type, pub, test) {
  if (type === 'wpkh') return bech32.encode(test ? 'tb' : 'bc', [0, ...bech32.toWords(h160(pub))]);
  if (type === 'pkh') return b58.encode(Uint8Array.of(test ? 0x6f : 0, ...h160(pub)));
  if (type === 'sh-wpkh') return b58.encode(Uint8Array.of(test ? 0xc4 : 5, ...h160(Uint8Array.of(0, 20, ...h160(pub)))));
  const xo = pub.slice(1), P = secp256k1.ProjectivePoint.fromHex('02' + hex(xo)), t = schnorr.utils.taggedHash('TapTweak', xo);
  const Q = P.add(secp256k1.ProjectivePoint.BASE.multiply(BigInt('0x' + hex(t))));
  return bech32m.encode(test ? 'tb' : 'bc', [1, ...bech32m.toWords(Q.toRawBytes(true).slice(1))]);
}

const entropyArb = fc.constantFrom(16, 20, 24, 28, 32).chain((n) => fc.uint8Array({ minLength: n, maxLength: n }));
const mnemonicArb = entropyArb.map((e) => entropyToMnemonic(e, wordlist));
// Passphrases: plain text, accented and composed/decomposed letters, CJK, emoji, spaces and odd whitespace.
const passArb = fc.oneof(fc.constant(''), fc.string({ maxLength: 20 }), fc.string({ unit: 'grapheme', maxLength: 12 }),
  fc.array(fc.constantFrom('a', 'Z', 'é', 'é', 'ß', 'ﬁ', '漢', '字', '😀', ' ', '  ', '　', ' ', 'İ', 'Å', 'Å'), { maxLength: 10 }).map((a) => a.join('')));

// 1. Entropy to words: every length, every byte value.
await prop('BIP39: entropy to words matches @scure', entropyArb, async (e) => (await w.entropyToMnemonic(e)) === entropyToMnemonic(e, wordlist) || 'words differ for ' + hex(e));

// 2. Words and passphrase to seed (NFKD of both, as BIP39 says).
await prop('BIP39: words + passphrase to seed matches @scure (Unicode passphrases)', fc.tuple(mnemonicArb, passArb),
  async ([m, p]) => hex(await w.mnemonicToSeed(m, p)) === hex(mnemonicToSeedSync(m, p)) || 'seed differs for passphrase ' + JSON.stringify(p), Math.max(10, Math.ceil(RUNS / 3)));

// 3. Any path, any address type, both networks: the page's address equals the reference.
const stepArb = fc.tuple(fc.integer({ min: 0, max: 2147483647 }), fc.boolean());
await prop('BIP32: addresses on random paths (all four types, both networks) match @scure and @noble',
  fc.record({ e: fc.uint8Array({ minLength: 16, maxLength: 16 }), steps: fc.array(stepArb, { maxLength: 4 }), chain: fc.constantFrom(0, 1), idx: fc.integer({ min: 0, max: 2147483646 }), type: fc.constantFrom('wpkh', 'pkh', 'sh-wpkh', 'tr'), test: fc.boolean() }),
  async ({ e, steps, chain, idx, type, test }) => {
    const seed = mnemonicToSeedSync(entropyToMnemonic(e, wordlist), '');
    const path = 'm' + steps.map(([i, h]) => '/' + i + (h ? "'" : '')).join('') + '/' + chain + '/' + idx;
    const got = (await w.walletAddressesFrom(await w.masterFromSeed(seed), steps, type, test ? 'test' : 'main', chain, idx, 1))[0];
    const want = refAddr(type, HDKey.fromMasterSeed(seed).derive(path).publicKey, test);
    return (got.address === want && got.path === path) || path + ' ' + type + ': ' + got.address + ' != ' + want;
  }, Math.max(10, Math.ceil(RUNS / 2)));

// 4. The words checker agrees with @scure, also after one word is swapped for another BIP39 word.
await prop('VERIFY: a phrase with one word changed is valid exactly when @scure says so', fc.tuple(mnemonicArb, fc.nat(), fc.nat({ max: 2047 })),
  async ([m, pos, wi]) => { const a = m.split(' '); a[pos % a.length] = wordlist[wi]; const t = a.join(' '); return (await w.checkPhrase(t)).ok === validateMnemonic(t, wordlist) || 'disagree on: ' + t; });

// 5. Dice and coin rolls: words = BIP39 of the first 16 or 32 bytes of SHA-256 of the roll string.
await prop('Rolls: words from any roll string are BIP39 of SHA-256 of the rolls', fc.tuple(fc.stringMatching(/^[1-6]{1,300}$/), fc.constantFrom(12, 15, 18, 21, 24)),
  async ([r, wc]) => (await w.rollsToMnemonic(r, wc)) === entropyToMnemonic(nc.createHash('sha256').update(r).digest().subarray(0, wc * 4 / 3), wordlist) || 'rolls ' + r);   // v2.10.0: all five lengths

// 6. Dice passphrase: word i is bits 11i to 11i+10 of SHA-256 of the rolls.
await prop('Dice passphrase: words from any rolls follow SHA-256, 11 bits a word', fc.tuple(fc.stringMatching(/^[1-6]{20,80}$/), fc.constantFrom(6, 8)),
  async ([r, n]) => { const b = [...nc.createHash('sha256').update(r).digest()].map((x) => x.toString(2).padStart(8, '0')).join('');
    return (await w.dpWordsFrom(r, n)).join(' ') === Array.from({ length: n }, (_, i) => wordlist[parseInt(b.slice(i * 11, i * 11 + 11), 2)]).join(' '); });

// 7. Address decoding: random SegWit programs round-trip; one changed character is caught by the checksum.
await prop('Addresses: random SegWit v0/v1 programs decode back to the same bytes', fc.record({ v1: fc.boolean(), prog: fc.uint8Array({ minLength: 20, maxLength: 20 }), prog32: fc.uint8Array({ minLength: 32, maxLength: 32 }), test: fc.boolean() }),
  async ({ v1, prog, prog32, test }) => { const p = v1 ? prog32 : prog, a = (v1 ? bech32m : bech32).encode(test ? 'tb' : 'bc', [v1 ? 1 : 0, ...(v1 ? bech32m : bech32).toWords(p)]); const d = w.segwitDecode(a);
    return (!!d && hex(d.prog) === hex(p) && d.version === (v1 ? 1 : 0)) || 'decode failed for ' + a; });
await prop('Addresses: one changed character in a bech32 address is caught', fc.tuple(fc.uint8Array({ minLength: 20, maxLength: 20 }), fc.nat(), fc.nat({ max: 31 })),
  async ([p, pos, c]) => { const a = bech32.encode('bc', [0, ...bech32.toWords(p)]), i = 4 + (pos % (a.length - 4)), ch = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l'[c];
    if (a[i] === ch) return true; const b = a.slice(0, i) + ch + a.slice(i + 1); return w.segwitDecode(b) === null || 'not caught: ' + b; });
await prop('Base58Check: random payloads decode back; one changed character is caught', fc.tuple(fc.uint8Array({ minLength: 21, maxLength: 21 }), fc.nat(), fc.nat({ max: 57 })),
  async ([p, pos, c]) => { const a = b58.encode(p); if (hex(await w.base58decode(a)) !== hex(p)) return 'round trip failed for ' + a;
    const i = pos % a.length, ch = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'[c]; if (a[i] === ch) return true;
    try { await w.base58decode(a.slice(0, i) + ch + a.slice(i + 1)); return 'not caught: ' + a.slice(0, i) + ch + a.slice(i + 1); } catch (e) { return true; } });

// 8. Robustness: arbitrary text in the boxes that take any text never throws a non-Error or hangs.
const anyText = fc.oneof(fc.string({ maxLength: 120 }), fc.string({ unit: 'binary', maxLength: 60 }), fc.array(fc.constantFrom(...wordlist.slice(0, 50), '?', '1', 'bc1q', 'xpub', ' '), { maxLength: 30 }).map((a) => a.join(' ')));
await prop('Robustness: VERIFY, Explain an address and the Detective target take any text without crashing', anyText,
  async (t) => { await w.checkPhrase(t); await w.explainAddress(t); try { await w.detTarget(t); } catch (e) { if (!(e instanceof w.Error) && !(e instanceof Error)) return 'threw a non-Error'; } return true; });

// 9. Electrum's own normalization: the page matches Electrum's Python normalize_text on a fixed set of hard cases
// (tests/fixtures/electrum-normalize.json, made with electrum/mnemonic.py), and on random input it is stable.
{ const F = JSON.parse(fs.readFileSync(new URL('./fixtures/electrum-normalize.json', import.meta.url), 'utf8'));
  const bad = F.cases.filter(([a, b]) => w.electrumNorm(a) !== b);
  R.ok(bad.length === 0, 'Electrum: normalize_text matches Electrum on ' + F.cases.length + ' hard cases' + (bad.length ? ' (first mismatch: ' + JSON.stringify(bad[0]) + ')' : '')); }
await prop('Electrum: normalizing twice changes nothing', anyText, async (t) => w.electrumNorm(w.electrumNorm(t)) === w.electrumNorm(t));

R.done('fuzz');
